begin;
do $$declare owner_id uuid;layout jsonb;copy uuid;returned jsonb;begin
 select user_id into owner_id from portfolio_api.admins limit 1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','aal','aal2')::text,true);
 layout:=public.portfolio_studio('layout');
 perform public.portfolio_studio('save_layout',layout||jsonb_build_object('maintenance_enabled',true,'maintenance_until',now()+interval '1 hour'));
 if (public.portfolio_studio('layout')->>'maintenance_until')::timestamptz is distinct from now()+interval '1 hour' then raise exception 'Deadline save failed';end if;
 copy:=portfolio_api.copy_layout((select id from portfolio_api.layouts where revision_kind='DRAFT'),'HISTORY');
 if (portfolio_api.layout_data(copy)->>'maintenance_until')::timestamptz is distinct from now()+interval '1 hour' then raise exception 'History lost deadline';end if;
 update portfolio_api.layouts set maintenance_enabled=true,maintenance_until=now()+interval '1 hour' where revision_kind='LIVE';
 if not portfolio_api.maintenance_active() then raise exception 'Future maintenance not active';end if;
 if not(public.portfolio_manage('health')->>'maintenance')::boolean then raise exception 'Health missed active maintenance';end if;
 returned:=public.portfolio_site();
 if returned ? 'projects' or not(returned->'layout'->>'maintenance_enabled')::boolean then raise exception 'Maintenance leaked published content';end if;
 if public.portfolio_blog(null)<>'[]'::jsonb then raise exception 'Maintenance leaked blog';end if;
 update portfolio_api.layouts set maintenance_until=now()-interval '1 second' where revision_kind='LIVE';
 if portfolio_api.maintenance_active() then raise exception 'Expired maintenance still active';end if;
 if(public.portfolio_manage('health')->>'maintenance')::boolean then raise exception 'Health still reports expired maintenance';end if;
 returned:=public.portfolio_site();
 if not(returned ? 'projects') or (returned->'layout'->>'maintenance_enabled')::boolean then raise exception 'Expired maintenance failed to restore portfolio';end if;
 if public.portfolio_blog(null) is distinct from portfolio_api.blog_without_maintenance(null) then raise exception 'Blog did not resume';end if;
 if position('portfolio_api.maintenance_active()' in pg_get_functiondef('portfolio_api.inbox_guard()'::regprocedure))=0 then raise exception 'Contact gate does not respect expiry';end if;
 update portfolio_api.layouts set maintenance_until=null where revision_kind='LIVE';
 if not portfolio_api.maintenance_active() then raise exception 'Indefinite maintenance should stay on';end if;
 perform public.portfolio_studio('save_layout',layout||'{"maintenance_until":null}');
 if public.portfolio_studio('layout')->>'maintenance_until' is not null then raise exception 'Clearing schedule failed';end if;
 if has_function_privilege('anon','portfolio_api.maintenance_active()','execute') then raise exception 'Private helper exposed';end if;
end $$;
rollback;
